// Builds src/icons/glyphs.ts from the custom glyph sources in design/assets/icons.
// `--check` fails when the generated file is stale.
import { readdirSync, readFileSync, writeFileSync } from 'node:fs'
import { join } from 'node:path'

export const SOURCE_DIR = join(import.meta.dir, '../../../design/assets/icons')
export const OUTPUT = join(import.meta.dir, '../src/icons/glyphs.ts')

const TAGS = new Set(['path', 'circle', 'rect', 'line', 'polyline', 'ellipse'])
const ROOT = {
  viewBox: '0 0 24 24',
  fill: 'none',
  stroke: 'currentColor',
  'stroke-width': '1.75',
  'stroke-linecap': 'round',
  'stroke-linejoin': 'round',
}

type Node = [tag: string, attrs: Record<string, string>]

/** Reads one glyph, enforcing Lucide's drawing rules. */
export function parseGlyph(name: string, svg: string): Node[] {
  const root = svg.match(/<svg\b([^>]*)>/)?.[1]
  if (!root) throw new Error(`${name}: no <svg> element`)
  const rootAttrs = Object.fromEntries(
    [...root.matchAll(/([\w-:]+)="([^"]*)"/g)].map((m) => [m[1], m[2]]),
  )
  for (const [key, value] of Object.entries(ROOT))
    if (rootAttrs[key] !== value) throw new Error(`${name}: <svg> needs ${key}="${value}"`)
  const body = svg.slice(svg.indexOf('>', svg.indexOf('<svg')) + 1, svg.lastIndexOf('</svg>'))
  const nodes: Node[] = []
  for (const m of body.replace(/<!--[\s\S]*?-->/g, '').matchAll(/<(\w+)\b([^>]*?)\/?>/g)) {
    const tag = m[1] as string
    if (!TAGS.has(tag)) throw new Error(`${name}: <${tag}> isn't allowed`)
    const attrs = Object.fromEntries(
      [...(m[2] as string).matchAll(/([\w-:]+)="([^"]*)"/g)].map((a) => [a[1], a[2]]),
    )
    for (const banned of ['transform', 'fill', 'stroke', 'stroke-width', 'style', 'class'])
      if (banned in attrs) throw new Error(`${name}: ${banned} isn't allowed on <${tag}>`)
    nodes.push([tag, attrs])
  }
  if (!nodes.length) throw new Error(`${name}: empty glyph`)
  return nodes
}

export function glyphsTs(): string {
  const files = readdirSync(SOURCE_DIR)
    .filter((f) => f.endsWith('.svg'))
    .sort()
  const entries = files.map((file) => {
    const name = file.slice(0, -4)
    const nodes = parseGlyph(name, readFileSync(join(SOURCE_DIR, file), 'utf8'))
    const body = nodes
      .map(([tag, attrs], i) => {
        const pairs = Object.entries({ ...attrs, key: String(i) })
          .map(([k, v]) => `${/^[a-z]+$/.test(k) ? k : `'${k}'`}: '${v}'`)
          .join(', ')
        return `    ['${tag}', { ${pairs} }],`
      })
      .join('\n')
    return `  '${name}': [\n${body}\n  ],`
  })
  return `// SPDX-License-Identifier: AGPL-3.0-only
// Generated by scripts/icons.ts from design/assets/icons. Do not edit.
import type { IconNode } from 'lucide-react'

export const glyphs = {
${entries.join('\n')}
} satisfies Record<string, IconNode>
`
}

if (import.meta.main) {
  const next = glyphsTs()
  const current = (() => {
    try {
      return readFileSync(OUTPUT, 'utf8')
    } catch {
      return ''
    }
  })()
  if (process.argv.includes('--check')) {
    if (current !== next) {
      console.error('src/icons/glyphs.ts is stale: run `bun run build` in packages/ui-web')
      process.exit(1)
    }
    console.log('icons up to date')
  } else if (current !== next) {
    writeFileSync(OUTPUT, next)
    console.log('wrote src/icons/glyphs.ts')
  } else console.log('icons up to date')
}
